package me.jackstar.drakescrates.oracle;

import me.jackstar.drakescraft.utils.MessageUtils; import org.bukkit.Bukkit; import org.bukkit.OfflinePlayer; import org.bukkit.command.*; import org.bukkit.entity.Player; import java.util.*;
public final class OraculoCommand implements CommandExecutor {
 private final OracleService service;private final OracleYamlRepository relicaries;private final OracleGuiService gui;private final Runnable reload;
 public OraculoCommand(OracleService service,OracleYamlRepository relicaries,OracleGuiService gui,Runnable reload){this.service=service;this.relicaries=relicaries;this.gui=gui;this.reload=reload;}
public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(args.length==0){if(sender instanceof Player p)gui.open(p);else MessageUtils.send(sender,"<red>Use /oraculo givekey from the console.");return true;}if("reclamar".equalsIgnoreCase(args[0])){if(!(sender instanceof Player p)){MessageUtils.send(sender,"<red>This command requires a player.");return true;}int claimed=service.claimAll(p);MessageUtils.send(p,claimed==0?"<gray>You have no pending rewards.":"<green>You claimed <yellow>"+claimed+" <green>Oracle reward(s).");return true;}if(!sender.hasPermission("drakescrates.admin")){MessageUtils.send(sender,"<red>No permission.");return true;}try{if("reload".equalsIgnoreCase(args[0])){reload.run();MessageUtils.send(sender,"<green>Oracle reloaded.");return true;}if(args.length<4){MessageUtils.send(sender,"<red>/oraculo givekey|takekey|setpity <player> <relicary> <amount>");return true;}OfflinePlayer target=Bukkit.getOfflinePlayer(args[1]);String relicary=args[2].toLowerCase(Locale.ROOT);int amount=Integer.parseInt(args[3]);if(relicaries.get(relicary)==null)throw new IllegalArgumentException("Unknown relicary");switch(args[0].toLowerCase(Locale.ROOT)){case "givekey"->service.give(target.getUniqueId(),relicary,amount);case "takekey"->{if(!service.take(target.getUniqueId(),relicary,amount))throw new IllegalArgumentException("Insufficient balance");}case "setpity"->service.setPity(target.getUniqueId(),relicary,amount);default->{MessageUtils.send(sender,"<red>Unknown action.");return true;}}MessageUtils.send(sender,"<green>Oracle updated for <yellow>"+target.getName()+"</yellow>.");}catch(Exception ex){MessageUtils.send(sender,"<red>"+ex.getMessage()+"</red>");}return true;}
}
